using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputCompactionProof {static int Main(string[] a){try{byte[] work=File.ReadAllBytes(a[0]),items=File.ReadAllBytes(a[1]);int total=int.Parse(a[2]),count=0;while(count*60+60<=work.Length&&BitConverter.ToSingle(work,count*60)!=0)count++;int at=0,checks=0;for(int n=0;n<total;n++){int length=((int)BitConverter.ToSingle(items,at)+1)*4;if(n>=total-count){int k=n-(total-count);var p=new float[15];Buffer.BlockCopy(work,k*60,p,0,60);byte[] actual=InputRecordCompaction.Compact(p);if(actual.Length!=length)throw new Exception("Record "+k+" bytes "+actual.Length+" != "+length);for(int b=0;b<length;b++)if(actual[b]!=items[at+b])throw new Exception("Record "+k+" byte "+b);checks+=length;}at+=length;}Console.WriteLine("PASS "+count+" original compact records, "+checks+" exact bytes.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
